functions.luckyDraw2:
{
   var _loc3_ = random(10000);
   if(_loc3_ < 2000)
   {
      _parent._parent.createThing({type:"幻魔之心"});
      _global.sysMsg.addMsg("获得 幻魔之心");
   }
   else if(_loc3_ < 4500)
   {
      _parent._parent.createThing({type:"小魔石袋子"});
      _global.sysMsg.addMsg("获得 小魔石袋子");
   }
   else if(_loc3_ < 7000)
   {
      _parent._parent.createThing({type:"中魔石袋子"});
      _global.sysMsg.addMsg("获得 中魔石袋子");
   }
   else if(_loc3_ < 9500)
   {
      _parent._parent.createThing({type:"大魔石袋子"});
      _global.sysMsg.addMsg("获得 大魔石袋子");
   }
   else
   {
      _parent._parent.createThing({type:"圣天使雷斯"});
      _global.sysMsg.addMsg("获得 圣天使雷斯");
   }
}

